mapper.select:
SELECT id, proCode, proName, proDesc, proContact, proPhone, proAddress, proFax, createdBy, creationDate, modifyDate, modifyBy, companyLicPicPath, orgCodePicPath, approvalStatus FROM tb_provider
AND proCode LIKE CONCAT('%', #{proCode}, '%')
AND proName LIKE CONCAT('%', #{proName}, '%')
AND createdBy = #{createdBy}
ORDER BY creationDate DESC LIMIT #{start}, #{size}

mapper.update:
UPDATE tb_provider
proCode = #{proCode}, proName = #{proName}, proDesc = #{proDesc}, proContact = #{proContact}, proPhone = #{proPhone}, proAddress = #{proAddress}, proFax = #{proFax}, companyLicPicPath = #{companyLicPicPath}, orgCodePicPath = #{orgCodePicPath}, approvalStatus = #{approvalStatus}, modifyBy = #{modifyBy}, modifyDate = NOW()
WHERE id = #{id}
